import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"54、【歸妹】 兌下震上","description":"周易口訣義 - 54、【歸妹】 兌下震上","frontmatter":{"title":"54、【歸妹】 兌下震上","description":"周易口訣義 - 54、【歸妹】 兌下震上"},"headers":[],"relativePath":"classics/koujueyi/056.md","filePath":"classics/koujueyi/056.md"}'),r={name:"classics/koujueyi/056.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_54、【歸妹】-兌下震上" tabindex="-1">54、【歸妹】 兌下震上 <a class="header-anchor" href="#_54、【歸妹】-兌下震上" aria-label="Permalink to “54、【歸妹】 兌下震上”">​</a></h1><p>彖曰：歸妹，天地之大義也。天地不交而萬物不興。「歸妹」，人之終始也。說以動，所「歸妹」也。「徵兇」，位不當也。「無攸利」，柔乘剛也。</p><p>象曰：澤上有雷，「歸妹」。君子以永終知敝。</p><p>初九：歸妹以娣，跛能履，徵吉。</p><p>象曰：「歸妹以娣」，以恆也。「跛能履吉」，相承也。</p><p>九二，眇能視，利幽人之貞。</p><p>象曰：「利幽人之貞」，未變常也。</p><p>六三，歸妹以須，反歸以娣。</p><p>象曰：「歸妹以須」，未當也。</p><p>九四，歸妹愆期，遲歸有時。</p><p>象曰：「愆期」之志，有待而行也。</p><p>六五，帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。</p><p>象曰：「帝乙歸妹，不如其娣之袂良」也，其位在中，以貴行也。</p><p>上六，女承筐無實，士刲羊無血，無攸利。</p><p>象曰：上六「無實」，承虛筐也。</p><p>解讀</p><p>歸妹者，女人以嫁為歸，歸妹即是從姊而嫁，故曰「歸妹」也。然古者諸侯一娶九女，侄娣從之。虞翻雲：「九女者，貴其男女繼嗣，宗享不絕也。」「徵兇無攸利」者，徵謂進而求寵也，妹從姊而行，固宜卑退，敬事女後，若妄求進寵，希謂並後，即有並後之亂，兇禍斯至而無利，故曰「徵兇無攸利」也。</p><p>象曰「澤上有雷，歸妹」者，澤上有雷，悅而有動，「歸妹之象也。君子以永終知敝」者，諸儒於此，各以意見，互說不同，不可隨波而流，彌增惑亂，今則取師說為義也。所以一娶九女者，貴其蕃育繼嗣，宗享不絕，則是永長延祚，保後之終。若九女無子，即絕其後嗣，即有不終之敝。蓋為正經雲「天地之大義」，人倫之終始矣。</p><p>「初九，歸妹以娣，跛能履，徵吉」者，少女謂之娣也。以兌適震，以幼從長，非其匹配，是從姊而行，故「歸妹以娣」也。雖不失其道，然幼從長，譬之跛足之人，足雖蹇跛，不妨履踐，故曰「跛能履」。妹從姊行，不可僭進，為嫡即兇，為娣即吉，故曰「徵吉」也。</p><p>「九二，眇能視，利幽人之貞」者，位雖不正，而居內處中，守其卑禮，不能妄進，猶如眇目之人，不妨所視，故曰「眇能視」也；居內守中，不失常道，是居幽而不虧其正，故曰「利幽人之貞」也。</p><p>「六三，歸妹以須，反歸以娣」者，六三處下卦之上，位又不正，即是僭進，求為室主，室主猶存，進不值時，故宜待時，故曰「歸妹以須」也；既不值時，固當反歸，且為娣從，俟時而進，故曰「反歸以娣」也。</p><p>「九四，歸妹愆期，遲歸有時」者，以陽居陰位不正也；下又無應，以不正無應而行，是為妄進，故須愆過於期，若有所適，候彼道窮盡，待時而行，然後可往，故「遲歸有時」也。</p><p>「六五，帝乙歸妹，其君之袂，不如其娣之袂良。月幾望，吉」者，居得尊位，應在九二，是帝王嫁妹，以降於二，故曰「帝乙歸妹」。袂者，衣袖為禮容，帝王嫁妹，則以衣裳為崇飾也。其君即五也，應在九二，以震適兌，以長從幼，即是降尊就卑，不如以卑就尊，合於常道，故曰「君之袂，不如其娣之袂良」。月，陰之盛，猶如月，近望可以敵日，以貴而行，以斯適配，往亦必合，故「月幾望，吉」。幾，近也；陰盛為位在於中，以貴而行也。</p><p>「上六，女承筐無實，士刲羊無血，無攸利」者，女子之行，以承順為德，士之為道，以下之應命為美。今上六居卦之上而無承應，其猶女子承捧虛筐，空無所有。筐本盛幣帛，今既空虛，即上無所奉，故曰「女承筐無實」也。下既無應，人不奉命，譬之刲刺其羊而無血矣。羊本有血，今既無血，即是教令不行，故曰「士刲羊無血」。進退莫與，故曰「無攸利」。羊謂六三也。</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
